/**
 * lib/trade.ts
 * Types, loader, and arc-builder for bilateral trade data.
 * Data is generated by scripts/fetch-trade.ts → data/trade.json.
 */

import tradeRaw from '@/data/trade.json';
import { countries, Country } from '@/lib/data';

// ── Shared types (also used by CountryPanel and Globe) ────────────────────────

export interface TradePartner {
  code: string;   // ISO3
  name: string;
  value: number;  // USD
  share: number;  // 0–100 (% of total)
}

export interface CountryTrade {
  year: number;
  exports: number | null;
  imports: number | null;
  exportPartners: TradePartner[];
  importPartners: TradePartner[];
}

export interface TradeArcDatum {
  startLat: number;
  startLng: number;
  endLat: number;
  endLng: number;
  value: number;
  type: 'export' | 'import';
  partnerCode: string;
  partnerName: string;
}

// ── Data accessors ────────────────────────────────────────────────────────────

const data = tradeRaw as Record<string, CountryTrade>;

export function getCountryTrade(iso3: string): CountryTrade | null {
  return data[iso3] ?? null;
}

// ── Arc builder ───────────────────────────────────────────────────────────────

const countryByISO3 = new Map(countries.map(c => [c.code3, c]));

/**
 * Build TradeArcDatum[] for globe.gl arcsData.
 * Export arcs go FROM selected country TO partner (green).
 * Import arcs go FROM partner TO selected country (amber).
 */
export function buildTradeArcs(country: Country, maxEach = 5): TradeArcDatum[] {
  const trade = getCountryTrade(country.code3);
  if (!trade) return [];

  const arcs: TradeArcDatum[] = [];

  for (const p of trade.exportPartners.slice(0, maxEach)) {
    const partner = countryByISO3.get(p.code);
    if (!partner) continue;
    arcs.push({
      startLat: country.lat,
      startLng: country.lng,
      endLat: partner.lat,
      endLng: partner.lng,
      value: p.value,
      type: 'export',
      partnerCode: p.code,
      partnerName: p.name,
    });
  }

  for (const p of trade.importPartners.slice(0, maxEach)) {
    const partner = countryByISO3.get(p.code);
    if (!partner) continue;
    arcs.push({
      startLat: partner.lat,
      startLng: partner.lng,
      endLat: country.lat,
      endLng: country.lng,
      value: p.value,
      type: 'import',
      partnerCode: p.code,
      partnerName: p.name,
    });
  }

  return arcs;
}
